// La web firma «timestamp.cuerpo» con HMAC-SHA256 (src/lib/leads.ts → firmarWebhook)
const crypto = require('crypto');
const entrada = $input.first();
const cabeceras = entrada.json.headers ?? {};
const timestamp = Number(cabeceras['x-iac-timestamp']);
const firma = String(cabeceras['x-iac-firma'] ?? '');
let crudo;
try {
  crudo = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch {
  crudo = JSON.stringify(entrada.json.body);
}
const esperada = 'sha256=' + crypto.createHmac('sha256', $env.IAC_WEBHOOK_SECRET).update(`${timestamp}.${crudo}`).digest('hex');
const aTiempo = Number.isFinite(timestamp) && Math.abs(Date.now() / 1000 - timestamp) < 300;
const coincide = firma.length === esperada.length && crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperada));
if (!aTiempo || !coincide) throw new Error('Aviso rechazado: firma u hora no válidas');
const aviso = JSON.parse(crudo);
return [{ json: { fecha: aviso.fecha, ...aviso.lead } }];

