      "description": "alta si menciona plazos inmediatos, errores o pérdidas; baja si solo explora"
    },
    "resumen": {
      "type": "string",
      "description": "Una frase en español de España con lo que necesita"
    },
    "siguiente_paso": {
      "type": "string",
      "description": "Qué preparar o preguntar en la llamada, en una frase"
    }
  },
  "required": ["categoria", "urgencia", "resumen", "siguiente_paso"]
}

