// Une el lead con la clasificación de Claude: los nombres coinciden con las columnas de la tabla
const lead = $('Verificar firma').first().json;
const ia = $input.first().json.output ?? {};
return [{ json: {
  fecha: lead.fecha,
  nombre: lead.nombre,
  telefono: lead.telefono,
  empresa: lead.empresa || '',
  proceso: lead.proceso,
  franja: lead.franja,
  motivo: lead.motivo,
  origen: lead.origen,
  categoria: ia.categoria ?? 'otro',
  urgencia: ia.urgencia ?? 'media',
  resumen: ia.resumen ?? '',
  siguiente_paso: ia.siguiente_paso ?? '',
} }];
